'use strict';
const $ = (selector, root=document) => root.querySelector(selector);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {session:null, studies:[], study:null, view:'overview', route:0};
const sections=[['overview','Overview'],['documentation','Living documentation'],['document','Document library'],['discussion','Discussions'],['task','Tasks & decisions'],['idea','Ideas & whiteboards'],['handoff','Handoff snapshots'],['activity','Activity & lifecycle']];
const titles={documentation:'Living documentation',document:'Document library',discussion:'Discussions',task:'Tasks & decisions',idea:'Ideas & whiteboards'};
const liveFiles=()=> (state.study?.files||[]).filter(f=>!f.deleted);
const date=value=>value?new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'Date unavailable';
const items=(kind)=> (state.study?.items||[]).filter(i=>!i.deleted&&(!kind||i.kind===kind));
const badge=stage=>`<span class="pill ${escape(String(stage).toLowerCase())}">${escape(stage)}</span>`;
function notice(message,error=false){const node=$('#notice');node.textContent=message;node.hidden=!message;node.className=`notice${error?' error':''}`;if(error)node.scrollIntoView({block:'nearest'});}
async function api(path, data){const response=await fetch(path,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json','X-CSRF-TOKEN':state.session?.csrf||''}:{},body:data?JSON.stringify(data):undefined});let body;try{body=await response.json();}catch{body={};}if(!response.ok)throw new Error(body.message||body.error||body.title||`Request could not be completed (${response.status}).`);return body;}
async function refreshSession(){state.session=await api('/api/session');const identities=state.session.identities||[];$('#identity').innerHTML=identities.map(i=>`<option value="${escape(i.id)}" ${i.id===state.session.user.id?'selected':''}>${escape(i.name)}</option>`).join('');$('#admin-nav').hidden=state.session.user.role!=='Administrator';}
async function route(){const ticket=++state.route;notice('');const parts=location.hash.slice(1).split('/');state.study=null;$('#main').setAttribute('aria-busy','true');try{if(parts[0]==='admin'){const admin=await api('/api/admin');if(ticket!==state.route)return;renderAdmin(admin);}else if(parts[0]==='study'&&parts[1]){const study=await api(`/api/studies/${encodeURIComponent(parts[1])}`);if(ticket!==state.route)return;state.study=study;[state.protocolAvailability,state.documentWorkspace]=await Promise.all([api(`/api/studies/${encodeURIComponent(study.id)}/protocol`),api(`/api/studies/${encodeURIComponent(study.id)}/documents`)]);if(ticket!==state.route)return;state.view=sections.some(s=>s[0]===parts[2])?parts[2]:'overview';renderStudy();if(state.view==='handoff')loadHandoffs();if(parts[3]){const target=document.getElementById('record-'+decodeURIComponent(parts[3]));if(target){target.tabIndex=-1;target.scrollIntoView({block:'center'});target.focus();}}if(state.view==='activity'&&state.session.user.role==='Administrator')loadImportReports();}else{const studies=await api('/api/studies');if(ticket!==state.route)return;state.studies=studies;renderStudies();}$('#studies-nav').setAttribute('aria-current',parts[0]==='admin'?'false':'page');$('#admin-nav').setAttribute('aria-current',parts[0]==='admin'?'page':'false');}catch(error){$('#main').innerHTML=`<div class="panel empty"><h1>Workspace unavailable</h1><p>${escape(error.message)}</p><a href="#studies">Return to My studies</a></div>`;}finally{$('#main').removeAttribute('aria-busy');}}
function renderStudies(){const studies=state.studies;$('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">Your research workspace</p><h1>My studies</h1><p class="muted">Shared context. Clear next steps. A lasting record of your team's work.</p></div><span class="count-badge">${studies.length} accessible ${studies.length===1?'study':'studies'}</span></div><div class="study-grid">${studies.map((s,n)=>`<article class="study-card"><div class="card-top">${badge(s.stage)}<span class="muted">STUDY ${String(n+1).padStart(2,'0')}</span></div><h2><a href="#study/${encodeURIComponent(s.id)}/overview">${escape(s.title)}</a></h2><p>${escape(s.summary)}</p><div class="card-bottom"><span class="muted">Group-based access</span><a href="#study/${encodeURIComponent(s.id)}/overview">Open workspace <span aria-hidden="true">→</span></a></div></article>`).join('')||'<div class="panel empty wide"><h2>No study access</h2><p>This identity has no mapped study-group membership. Administrative roles do not grant study content access.</p></div>'}</div><section class="welcome-strip"><span class="welcome-icon" aria-hidden="true">↗</span><div><h2>Pick up where the work left off</h2><p>Each workspace brings together the current plan, versioned documents, conversations, and decisions. Use the demo identity selector to explore how group access changes.</p></div></section><div class="overview-grid integrations-grid"><div class="integration"><strong>Study assistant · Disabled</strong>No AI requests or generated research conclusions. Core study work is available independently.</div><div class="integration"><strong>Teams connection · Disabled</strong>No messages are sent or synchronized. The study record stays in this local application.</div></div>`;}
function renderStudy(){const s=state.study;document.title=`${s.title} · Research Collaboration Hub`;$('#main').innerHTML=`<div class="breadcrumb"><a href="#studies">My studies</a> <span aria-hidden="true"> / </span> Study workspace</div><div class="page-heading"><div><p class="eyebrow">Study workspace</p><h1>${escape(s.title)}</h1><p class="muted">${escape(s.summary)}</p></div>${badge(s.stage)}</div><div class="study-shell"><nav class="study-nav" aria-label="Study sections"><p>Workspace</p>${sections.map(([id,label])=>`<a href="#study/${encodeURIComponent(s.id)}/${id}" ${id===state.view?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div id="study-content">${state.view==='overview'?overview():state.view==='activity'?activity():state.view==='handoff'?handoffWorkspace():collection()}</div></div>`;}
function linkView(view,label){return `<a class="small-link" href="#study/${encodeURIComponent(state.study.id)}/${view}">${label} <span aria-hidden="true">→</span></a>`;}
function overview(){const docs=items('document').sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));const questions=items('discussion');const tasks=items('task').filter(i=>i.task?.status!=='Done');const decisions=items('decision');return `<div class="content-heading"><h2>At a glance</h2><span class="screen-note">Workspace revision ${state.study.revision}</span></div><div class="overview-grid">${protocolPanel()}<section class="panel"><p class="label">People & access</p><h3>${state.study.id==='atlas'?'Riley · synthetic study lead':'Sam · synthetic study contact'}</h3><p class="screen-note">Study contact for this demonstration. Contact details are synthetic.</p><strong>${escape(state.session.user.name)}</strong><p class="muted">Signed in as a synthetic study participant.</p><p class="screen-note">Membership is derived from the mapped demo directory group. Assignment or an application role does not grant membership.</p></section><section class="panel"><div class="row-head"><h2>Open conversations</h2>${linkView('discussion','View all')}</div>${questions.slice(0,3).map(i=>`<div class="recent-item"><a href="#study/${encodeURIComponent(state.study.id)}/discussion">${escape(i.title)}</a><div class="muted">${escape(i.author)} · ${date(i.createdAt)}</div></div>`).join('')||'<p class="muted">No questions yet. Start a discussion around the current plan.</p>'}</section><section class="panel"><div class="row-head"><h2>Next actions</h2>${linkView('task','View plan')}</div>${tasks.slice(0,3).map(i=>`<div class="recent-item"><strong>${escape(i.title)}</strong><div class="muted">${escape(i.body.slice(0,100))}</div></div>`).join('')||'<p class="muted">Capture the next step with its owner and supporting context.</p>'}</section><section class="panel wide"><h2>Start here</h2><ol class="onboarding-steps"><li>${linkView('documentation','Read the study orientation')}</li><li>${linkView('document','Review the current document family and review state')}</li><li>${linkView('discussion','Follow the open questions and their evidence')}</li><li>${linkView('task','Confirm the next action and its owner')}</li><li>${linkView('handoff','Review a fixed handoff snapshot')}</li></ol></section><section class="panel wide"><div class="row-head"><h2>Recent decisions</h2>${linkView('task','Decision trail')}</div>${decisions.slice(-2).reverse().map(i=>record(i,false)).join('')||'<p class="muted">Decisions will appear here with their rationale and evidence.</p>'}</section></div>`;}
function collection(){const view=state.view;const descriptions={documentation:'Living notes and onboarding context. These notes retain earlier entries; the document library provides governed Draft, Review, and Accepted versions.',document:'Every revision retains its author and context. Text documents and synthetic file attachments are available in this preview.',discussion:'Ask a question, follow the replies, and link the exact evidence that informed the conversation.',task:'Keep next actions and decisions together with their rationale and supporting records.',idea:'An accessible, keyboard-friendly list for brainstorming. Each idea is retained as a study record.'};const labels={documentation:'Add documentation',document:'Add document',discussion:'Start discussion',task:'Add task',idea:'Capture idea'};let records=items(view);if(view==='task')records=items().filter(i=>['task','decision'].includes(i.kind));return `<div class="content-heading"><h2>${titles[view]}</h2><button class="usa-button" data-action="new" data-kind="${view}">${labels[view]}</button></div><p class="section-description">${descriptions[view]}</p><div id="editor"></div>${view==='document'?`<section class="panel"><div class="row-head"><h3>Uploaded files</h3><button class="text-button" data-action="upload">Upload file</button></div><p class="screen-note">Synthetic files only · 512 KiB maximum. File release uses a demo policy, not a malware scanner.</p>${liveFiles().map(fileRecord).join('')||'<p class="muted">No uploaded files yet.</p>'}</section>`:''}${view==='task'?'<p><button class="text-button" data-action="new" data-kind="decision">+ Record a decision</button></p>':''}${view==='idea'?`<ol class="idea-list">${records.map(i=>`<li><div>${record(i)}</div></li>`).join('')}</ol>${records.length?'':'<div class="panel empty"><h3>Make room for the next idea</h3><p>Capture a proposal, alternatives, or a question for the team.</p></div>'}`:`<section class="panel" aria-label="${titles[view]}">${(view==='document'?documentFamilies():records.map(i=>record(i)).join(''))||'<div class="empty"><h3>A shared record starts here</h3><p>Add the first item to this part of the workspace.</p></div>'}</section>`}`;}
function record(i,actions=true){const replies=items('reply').filter(r=>r.parentId===i.id);const evidence=i.parentId?items().find(r=>r.id===i.parentId):null;return `<article class="record" id="record-${escape(i.id)}"><div class="record-meta"><span>${escape(i.kind)}</span>${i.version?`<span>Version ${escape(i.version)}</span>`:''}<span>${escape(i.author)}</span><span>${date(i.createdAt)}</span></div><h3>${escape(i.title)}</h3>${i.kind==='document'?documentReviewSummary(i):''}<p>${escape(i.body)}</p>${i.kind==='task'?taskMetadata(i):''}${provenanceDetails(i)}${i.documentId?`<div class="screen-note">Document evidence: ${itemEvidence(i.documentId)}</div>`:''}${fileEvidence(i.fileIds||[])}${evidence?`<p class="screen-note">Linked evidence: ${escape(evidence.title)}${evidence.version?` · version ${escape(evidence.version)}`:''}</p>`:''}${actions?`<div class="record-actions">${['discussion','reply'].includes(i.kind)?`<button class="text-button" data-action="attach" data-id="${escape(i.id)}">Attach file</button>`:''}${i.kind==='task'?`<button class="text-button" data-action="edit-task" data-id="${escape(i.id)}">Update task</button>`:''}${['discussion','reply'].includes(i.kind)?`<button class="text-button" data-action="reply" data-id="${escape(i.id)}">Reply</button><button class="text-button" data-action="decision" data-id="${escape(i.id)}">Record decision</button>`:''}${i.kind==='document'?documentStateActions(i):''}${['document','documentation'].includes(i.kind)?`<button class="text-button" data-action="revise" data-id="${escape(i.id)}">Add revision</button>${i.kind==='document'?`<a class="small-link" href="/api/studies/${encodeURIComponent(state.study.id)}/documents/${encodeURIComponent(i.id)}/download">Download text</a>`:''}`:''}${i.kind==='idea'?`<button class="text-button" data-action="decision" data-id="${escape(i.id)}">Turn into decision</button>`:''}</div>`:''}${liveFiles().filter(f=>f.parentId===i.id).map(fileRecord).join('')}${replies.map(r=>`<div class="reply">${record(r,actions)}</div>`).join('')}</article>`;}
function activity(){const s=state.study;return `${protocolPanel(true)}${importPanel()}<div class="content-heading"><h2>Activity & lifecycle</h2></div><section class="panel"><h3>Study status</h3><p class="muted">This is a workspace status, not external study approval. Closed studies keep their record and can be reopened.</p><form id="stage-form" class="stage-form"><label for="stage">Workspace stage</label><select id="stage" name="stage" class="usa-select">${['Active','Paused','Closed'].map(stage=>`<option ${stage.toLowerCase()===s.stage.toLowerCase()?'selected':''}>${stage}</option>`).join('')}</select><button class="usa-button" type="submit">Update stage</button></form></section><section class="panel"><h3>Record history</h3>${items().slice().reverse().map(i=>`<div class="recent-item"><strong>${escape(i.title)}</strong><div class="muted">${escape(i.kind)} · ${escape(i.author)} · ${date(i.createdAt)}${i.version?' · version '+escape(i.version):''}</div></div>`).join('')}</section>`;}
function showEditor(kind,source=null,revision=false){if(kind==='task'){showTaskEditor(source);return;}if(kind==='document'){showDocumentEditor(source,revision);return;}const target=$('#editor');if(!target)return;const evidence=source&&!revision?source.id:'';const requestId=crypto.randomUUID();target.innerHTML=`<section class="form-panel"><h3>${revision?'Add a new revision':kind==='reply'?'Reply to discussion':'Add '+kind}</h3><form id="item-form" data-kind="${escape(kind)}" data-request="${requestId}" data-parent="${escape(evidence)}" data-document="${revision?escape(source.kind==='document'?source.id:source.documentId||''):''}"><label for="item-title" class="usa-label">${kind==='reply'?'Reply subject':'Title'}</label><input id="item-title" name="title" class="usa-input" required maxlength="160" value="${escape(revision?source.title:kind==='reply'?'Re: '+source.title:'')}"><label for="item-body" class="usa-label">${kind==='decision'?'Decision, rationale, and alternatives':kind==='task'?'Owner, next action, and evidence':'Content'}</label><textarea id="item-body" name="body" class="usa-textarea" required maxlength="20000">${escape(revision?source.body:'')}</textarea><p class="form-hint">Synthetic demonstration content only. Saved records retain author and time.</p>${!source&&['discussion','decision','task'].includes(kind)?`<label for="evidence" class="usa-label">Link exact document version (optional)</label><select class="usa-select" id="evidence" name="documentId"><option value="">No linked document</option>${items().filter(i=>i.kind==='document').map(i=>`<option value="${escape(i.id)}">${escape(i.title)}${i.version?' — v'+escape(i.version):''}</option>`).join('')}</select>`:''}${fileEvidencePicker('fileIds',revision?source.fileIds||[]:[])}${evidence?`<p class="form-hint">Linked to: ${escape(source.title)}</p>`:''}<div class="form-row"><button class="usa-button" type="submit">Save ${kind==='reply'?'reply':'record'}</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;$('#item-title').focus();}
function renderAdmin(data){state.configRevision=data.configRevision;const identities=(data.identities||[]).map(i=>({...i,role:data.roles?.[i.id]||'Researcher',groups:data.groups?.[i.id]||[],accessible:(data.effectiveAccess||[]).find(a=>a.identity===i.id)?.studies||[]}));const mappings=Array.isArray(data.mappings)?data.mappings:Object.entries(data.mappings||{}).map(([studyId,groupId])=>({studyId,groupId}));$('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">Service administration</p><h1>Access & configuration</h1><p class="muted">Manage application responsibilities and study group mappings. Directory membership remains authoritative.</p></div><span class="count-badge">Synthetic directory</span></div><div class="overview-grid"><section class="panel"><h2>Application roles</h2><p class="screen-note">An administrator can manage configuration without gaining study content access.</p><form id="role-form" data-revision="${data.configRevision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="role-identity">Synthetic identity</label><select id="role-identity" name="identity" class="usa-select">${identities.map(i=>`<option value="${escape(i.id)}">${escape(i.name)} (${escape(i.role)})</option>`).join('')}</select><label class="usa-label" for="role">Application role</label><select id="role" name="role" class="usa-select"><option>Researcher</option><option>Administrator</option></select><div class="form-row"><button class="usa-button" type="submit">Save role</button></div></form></section><section class="panel"><h2>Study group mapping</h2><p class="screen-note">Map a study to an existing synthetic group. This does not edit directory membership.</p><form id="mapping-form" data-revision="${data.configRevision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="mapping-study">Study</label><select id="mapping-study" name="studyId" class="usa-select">${mappings.map(m=>`<option value="${escape(m.studyId||m.id)}">${escape(m.title||m.studyId||m.id)}</option>`).join('')}</select><label class="usa-label" for="mapping-group">Stable group identifier</label><input id="mapping-group" name="groupId" class="usa-input" required maxlength="100" value="${escape(mappings[0]?.groupId||'')}"><div class="form-row"><button class="usa-button" type="submit">Save mapping</button></div></form></section><section class="panel wide"><h2>Effective access inputs</h2><p class="screen-note">Synthetic identity group claims and current mappings determine access. No separately maintained study roster.</p><div class="table-wrap" role="region" aria-label="Scrollable administration table" tabindex="0"><table class="usa-table"><caption class="usa-sr-only">Synthetic identity roles and groups</caption><thead><tr><th scope="col">Identity</th><th scope="col">Application role</th><th scope="col">Directory groups</th><th scope="col">Effective study access</th></tr></thead><tbody>${identities.map(i=>`<tr><th scope="row">${escape(i.name)}</th><td>${escape(i.role)}</td><td>${escape((i.groups||i.groupIds||[]).join(', ')||'No study groups')}</td><td>${escape(i.accessible.join(', ')||'No study access')}</td></tr>`).join('')}</tbody></table></div><div class="table-wrap" role="region" aria-label="Scrollable administration table" tabindex="0"><table class="usa-table"><caption class="usa-sr-only">Study to directory group mappings</caption><thead><tr><th scope="col">Study</th><th scope="col">Authoritative group</th></tr></thead><tbody>${mappings.map(m=>`<tr><th scope="row">${escape(m.title||m.studyId||m.id)}</th><td><code>${escape(m.groupId)}</code></td></tr>`).join('')}</tbody></table></div></section><section class="panel wide"><h2>Administrative audit</h2><div class="table-wrap" role="region" aria-label="Scrollable administration table" tabindex="0"><table class="usa-table"><caption class="usa-sr-only">Recent audited actions</caption><thead><tr><th scope="col">When</th><th scope="col">Actor</th><th scope="col">Action</th><th scope="col">Target</th></tr></thead><tbody>${(data.audit||[]).slice(-30).reverse().map(a=>`<tr><td>${escape(date(a.createdAt||a.at||a.timestamp))}</td><td>${escape(a.actor||a.identity)}</td><td>${escape(a.action)}</td><td>${escape(a.target||a.studyId)}</td></tr>`).join('')}</tbody></table></div></section><div class="integration"><strong>Directory integration · Not configured</strong>Production identity and revocation require on-premises validation. Demo identities are restricted to local development.</div><div class="integration"><strong>External integrations · Disabled</strong>AI and Teams are disabled. No external traffic is generated.</div></div>`;}
$('#identity').addEventListener('change',async e=>{e.target.disabled=true;try{await api('/api/session',{identity:e.target.value});await refreshSession();location.hash='#studies';await route();notice('Demo identity changed. Accessible studies have been refreshed.');}catch(error){notice(error.message,true);}finally{e.target.disabled=false;}});
$('#search-form').addEventListener('submit',async e=>{e.preventDefault();const q=$('#search').value.trim();if(!q)return;try{const result=await api('/api/search?q='+encodeURIComponent(q));const found=Array.isArray(result)?result:result.items||[];$('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">Permission-aware search</p><h1>Search results</h1><p class="muted">${found.length} results for “${escape(q)}” within your accessible studies.</p></div></div><section class="panel">${found.map(r=>{const i=r.item||r;return `<article class="record"><p class="record-meta">${escape(r.studyTitle||r.studyId)} · ${escape(i.kind)}</p><h2><a href="#study/${encodeURIComponent(r.studyId||i.studyId)}/${i.kind==='decision'?'task':i.kind==='reply'?'discussion':i.kind==='file'?'document':i.kind}">${escape(i.title)}</a></h2><p>${escape(i.body?.slice(0,250))}</p></article>`;}).join('')||'<div class="empty"><h2>No matching records</h2><p>Try another phrase. Inaccessible and deleted records are excluded.</p></div>'}</section>`;$('#main').focus();}catch(error){notice(error.message,true);}});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const source=items().find(i=>i.id===button.dataset.id);if(button.dataset.action==='cancel'){$('#editor').innerHTML='';$('.content-heading button')?.focus();}if(button.dataset.action==='new')showEditor(button.dataset.kind);if(button.dataset.action==='upload')showUploadEditor();if(button.dataset.action==='attach')showUploadEditor(source?.id);if(button.dataset.action==='file-version')showUploadEditor(null,liveFiles().find(f=>f.id===button.dataset.file));if(button.dataset.action==='document-state')showDocumentStateEditor(source,button.dataset.state);if(button.dataset.action==='edit-task')showTaskEditor(source);if(button.dataset.action==='reply')showEditor('reply',source);if(button.dataset.action==='decision')showEditor('decision',source);if(button.dataset.action==='revise')showEditor(source.kind,source,true);});
document.addEventListener('submit',async e=>{const form=e.target;if(!['item-form','document-form','document-state-form','task-form','protocol-form','upload-form','stage-form','mapping-form','role-form'].includes(form.id))return;e.preventDefault();const submit=$('button[type=submit]',form);submit.disabled=true;const fields=Object.fromEntries(new FormData(form));try{if(form.id==='document-form'){await api(`/api/studies/${encodeURIComponent(state.study.id)}/documents${form.dataset.previous?'/'+encodeURIComponent(form.dataset.previous)+'/versions':''}`,{title:fields.title,body:fields.body,fileIds:new FormData(form).getAll('fileIds'),expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});}else if(form.id==='document-state-form'){await api(`/api/studies/${encodeURIComponent(state.study.id)}/documents/${encodeURIComponent(form.dataset.version)}/state`,{status:form.dataset.state,reason:fields.reason,expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});}else if(form.id==='protocol-form'){const [kind,id]=fields.selection?fields.selection.split(':'):[null,null];await api(`/api/studies/${encodeURIComponent(state.study.id)}/protocol`,{kind,id,reason:fields.reason,expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});}else if(form.id==='upload-form'){const file=$('#upload-file').files[0];if(!file||file.size>512*1024)throw new Error('Choose a synthetic file no larger than 512 KiB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);await api(`/api/studies/${encodeURIComponent(state.study.id)}/files`,{name:file.name,contentBase64:btoa(binary),parentId:form.dataset.parent||null,documentId:form.dataset.file||null,expectedRevision:state.study.revision,requestId:form.dataset.request});}else if(form.id==='task-form'){await api(`/api/studies/${encodeURIComponent(state.study.id)}/tasks${form.dataset.task?'/'+encodeURIComponent(form.dataset.task):''}`,{...fields,assignee:fields.assignee||null,dueDate:fields.dueDate||null,links:new FormData(form).getAll('links'),fileLinks:new FormData(form).getAll('fileLinks'),expectedRevision:state.study.revision,requestId:form.dataset.request});}else if(form.id==='item-form'){await api(`/api/studies/${encodeURIComponent(state.study.id)}/items`,{...fields,fileIds:new FormData(form).getAll('fileIds'),kind:form.dataset.kind,parentId:fields.parentId||form.dataset.parent||null,documentId:fields.documentId||form.dataset.document||null,expectedRevision:state.study.revision,requestId:form.dataset.request});}else if(form.id==='stage-form'){await api(`/api/studies/${encodeURIComponent(state.study.id)}/stage`,{...fields,expectedRevision:state.study.revision,requestId:crypto.randomUUID()});}else await api('/api/admin/'+(form.id==='role-form'?'role':'mapping'),{...fields,expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request});await refreshSession();await route();$('#main').focus();notice('Saved. The shared record has been updated.');}catch(error){notice(error.message,true);const local=$('#form-error');if(local)local.textContent='Your draft is still here. If the workspace changed, copy your text before refreshing.';}finally{submit.disabled=false;}});
window.addEventListener('hashchange',()=>{route().then(()=>{if(!location.hash.slice(1).split('/')[3])$('#main').focus();});});
refreshSession().then(route).catch(error=>{$('#main').innerHTML=`<div class="panel empty"><h1>Unable to load the local demo</h1><p>${escape(error.message)}</p><p>Verify the application is running in Development on loopback.</p></div>`;});

function taskMetadata(item){
 const task=item.task;
 if(!task)return '<p class="screen-note">Legacy task note · update this task to add structured ownership and status.</p>';
 const person=state.session.identities.find(i=>i.id===task.assignee);
 return `<div class="task-facts"><span class="pill">${escape(task.status)}</span><span>Owner: ${escape(person?.name||task.assignee||'Unassigned')}</span><span>Due: ${escape(task.dueDate||'Not set')}</span></div>${task.links.length?`<p class="screen-note">Evidence: ${task.links.map(itemEvidence).join(' · ')}</p>`:''}${fileEvidence(task.fileLinks||[])}${task.history.length?`<details class="task-history"><summary>Task history (${task.history.length} previous ${task.history.length===1?'revision':'revisions'})</summary>${task.history.slice().reverse().map(v=>`<div class="reply"><p class="record-meta">Revision ${v.version} · ${escape(v.actor)} · ${date(v.at)}</p><h4>${escape(v.title)}</h4><p>${escape(v.body)}</p><p class="screen-note">${escape(v.status)} · Owner: ${escape(v.assignee||'Unassigned')} · Due: ${escape(v.dueDate||'Not set')}</p><p class="screen-note">Evidence: ${v.links.map(itemEvidence).join(' · ')||'None'}</p>${fileEvidence(v.fileLinks||[])}</div>`).join('')}</details>`:''}`;
}
async function showTaskEditor(source=null){
 const studyId=state.study.id;
 try{
 const assignees=await api(`/api/studies/${encodeURIComponent(studyId)}/assignees`);
 if(state.study?.id!==studyId||!$('#editor'))return;
 const task=source?.task;
 const links=task?.links||[source?.documentId].filter(Boolean);
 $('#editor').innerHTML=`<section class="form-panel"><h3>${source?'Update task':'Add task'}</h3><form id="task-form" data-task="${escape(source?.id||'')}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="item-title">Task title</label><input class="usa-input" id="item-title" name="title" maxlength="180" required value="${escape(source?.title||'')}"><label class="usa-label" for="item-body">Next action and context</label><textarea class="usa-textarea" id="item-body" name="body" required maxlength="20000">${escape(source?.body||'')}</textarea><div class="task-form-grid"><div><label class="usa-label" for="task-assignee">Responsible participant</label><select class="usa-select" id="task-assignee" name="assignee"><option value="">Unassigned</option>${assignees.map(i=>`<option value="${escape(i.id)}" ${i.id===task?.assignee?'selected':''}>${escape(i.name)}</option>`).join('')}</select></div><div><label class="usa-label" for="task-status">Status</label><select class="usa-select" id="task-status" name="status">${['Open','In progress','Blocked','Done'].map(status=>`<option ${status===task?.status?'selected':''}>${status}</option>`).join('')}</select></div><div><label class="usa-label" for="task-due">Due date (optional)</label><input class="usa-input" id="task-due" name="dueDate" type="date" min="1900-01-01" max="2100-12-31" value="${escape(task?.dueDate||'')}"></div></div><p class="form-hint">Only current study-group participants can be assigned. Assignment never grants access.</p><fieldset class="evidence-picker"><legend>Supporting records (optional)</legend>${items().filter(i=>['document','documentation','discussion','reply','decision','idea'].includes(i.kind)).map(i=>`<label><input type="checkbox" name="links" value="${escape(i.id)}" ${links.includes(i.id)?'checked':''}> ${escape(i.title)} · ${escape(i.kind)}${i.version?' v'+i.version:''}</label>`).join('')||'<p class="screen-note">No supporting records yet.</p>'}</fieldset>${fileEvidencePicker('fileLinks',task?.fileLinks||[])}<div class="form-row"><button class="usa-button" type="submit">Save task</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;
 $('#item-title').focus();
 }catch(error){notice(error.message,true);}
}

function fileRecord(file){
 const released=file.status==='DemoReleased';
 return `<article class="file-record"><div class="row-head"><strong>${escape(file.name)}</strong><span class="pill ${released?'':'paused'}">${released?'Demo released':'Quarantined'}</span></div><p class="record-meta">File version ${file.version} · ${(file.size/1024).toFixed(1)} KiB · ${escape(file.author)} · ${date(file.createdAt)}</p><p class="screen-note">${released?'Passed the narrow synthetic demonstration policy. This is not a malware scan.':'Download blocked. This file has not been released by the synthetic demonstration policy.'}</p><div class="record-actions">${released?`<a href="/api/studies/${encodeURIComponent(state.study.id)}/files/${encodeURIComponent(file.id)}/download">Download ${escape(file.name)}</a>`:'<span class="screen-note">Download unavailable while quarantined</span>'}<button class="text-button" data-action="file-version" data-file="${escape(file.id)}">Upload new version</button></div>${provenanceDetails(file)}<details class="file-details"><summary>File integrity and context</summary><p class="screen-note">SHA-256: <code>${escape(file.sha256)}</code></p><p class="screen-note">${file.parentId?'Attached to: '+escape(items().find(i=>i.id===file.parentId)?.title||'Unavailable discussion'):'Document library file'} · Family: <code>${escape(file.familyId)}</code></p></details></article>`;
}
function showUploadEditor(parentId=null,source=null){
 const editor=$('#editor');if(!editor)return;
 editor.innerHTML=`<section class="form-panel"><h3>${source?'Upload a new file version':'Upload synthetic file'}</h3><form id="upload-form" data-parent="${escape(source?.parentId||parentId||'')}" data-file="${escape(source?.id||'')}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="upload-file">Choose file</label><input class="usa-file-input" id="upload-file" name="file" type="file" accept=".txt,.pdf,.png,.jpg" required aria-describedby="upload-hint"><p id="upload-hint" class="form-hint">Synthetic TXT, PDF, PNG, or JPG only; 512 KiB maximum. All files begin behind the release policy. A demo setting may release UTF-8 text and the bundled synthetic PNG; other binaries remain quarantined. No malware scanner is connected.</p>${source?`<p class="screen-note">New version of ${escape(source.name)}. Prior versions remain available with their existing release status.</p>`:''}${parentId||source?.parentId?`<p class="screen-note">Attached to: ${escape(items().find(i=>i.id===(source?.parentId||parentId))?.title||'Discussion')}</p>`:''}<div class="form-row"><button class="usa-button" type="submit">Upload file</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;
 $('#upload-file').focus();
}

function fileIsAvailable(file){return !file.deleted&&file.status==='DemoReleased'&&(!file.parentId||items().some(i=>i.id===file.parentId));}
function itemEvidence(id){const item=items().find(i=>i.id===id);if(!item||(item.kind==='reply'&&!items().some(i=>i.id===item.parentId)))return `<span>Unavailable record (${escape(id)})</span>`;const label=`${escape(item.title)} · ${escape(item.kind)} version ${item.version}`;if(item.kind==='document')return `<a href="/api/studies/${encodeURIComponent(state.study.id)}/documents/${encodeURIComponent(id)}/download">${label}</a>`;const view=item.kind==='reply'?'discussion':item.kind==='decision'?'task':item.kind;return `<a href="#study/${encodeURIComponent(state.study.id)}/${view}/${encodeURIComponent(item.id)}">${label}</a>`;}

function fileEvidence(ids){return ids.length?`<div class="evidence-links"><span class="screen-note">Exact file evidence</span><ul>${ids.map(id=>{const file=(state.study.files||[]).find(f=>f.id===id);return `<li>${file&&fileIsAvailable(file)?`<a href="/api/studies/${encodeURIComponent(state.study.id)}/files/${encodeURIComponent(id)}/download">${escape(file.name)} · file version ${file.version}</a>`:`Unavailable file version (${escape(id)})`}</li>`;}).join('')}</ul></div>`:'';}
function fileEvidencePicker(name,selected=[]){const available=liveFiles().filter(fileIsAvailable);return `<fieldset class="evidence-picker"><legend>Exact file versions (optional)</legend>${available.map(file=>`<label><input type="checkbox" name="${name}" value="${escape(file.id)}" ${selected.includes(file.id)?'checked':''}> ${escape(file.name)} · file version ${file.version}</label>`).join('')||'<p class="screen-note">No released file versions available.</p>'}${selected.filter(id=>!available.some(f=>f.id===id)).map(id=>`<p class="screen-note">Previously linked file is unavailable (${escape(id)}). Saving will remove this citation from the new revision; history preserves it.</p>`).join('')}</fieldset>`;}
function protocolPanel(edit=false){
 const selected=state.study.currentProtocol;
 const selectionLabel=entry=>!entry?.kind?'No protocol designated':entry===selected&&state.protocolAvailability?.available===false?`<span>Unavailable designated ${escape(entry.kind)} version (${escape(entry.id)})</span>`:entry.kind==='item'?itemEvidence(entry.id):fileReference(entry.id);
 return `<section class="panel accent-panel"><p class="label">Current protocol · exact version</p>${selected?`<div class="protocol-title">${selectionLabel(selected)}</div><p class="screen-note">Selected by ${escape(selected.actor)} · ${date(selected.at)}</p><p>${escape(selected.reason)}</p>`:'<h3>No current protocol selected</h3><p class="muted">Choose an exact document version when the team agrees its working reference.</p>'}${selected?.kind==='item'?`<p class="screen-note">Document state: ${escape(state.documentWorkspace?.versions.find(v=>v.item.id===selected.id)?.status||'Unavailable')}</p>`:''}${selected&&state.protocolAvailability?.available===false?`<p class="notice error">${escape(state.protocolAvailability.error)}</p>`:''}<p class="screen-note">A workspace designation is not external study approval. Uploading a later version does not change this selection.</p>${edit?`<form id="protocol-form" data-revision="${state.study.revision}" data-request="${crypto.randomUUID()}"><label for="protocol-selection" class="usa-label">Current protocol version</label><select class="usa-select" id="protocol-selection" name="selection"><option value="">Clear current designation</option>${items('document').map(item=>`<option value="item:${escape(item.id)}" ${selected?.kind==='item'&&selected.id===item.id?'selected':''}>${escape(item.title)} · text version ${item.version}</option>`).join('')}${liveFiles().filter(f=>!f.parentId&&fileIsAvailable(f)).map(file=>`<option value="file:${escape(file.id)}" ${selected?.kind==='file'&&selected.id===file.id?'selected':''}>${escape(file.name)} · file version ${file.version}</option>`).join('')}</select><label class="usa-label" for="protocol-reason">Reason for selection or clearing</label><textarea class="usa-textarea" id="protocol-reason" name="reason" required maxlength="1000"></textarea><div class="form-row"><button class="usa-button" type="submit">Save protocol designation</button></div></form><details class="task-history"><summary>Protocol designation history (${(state.study.protocolHistory||[]).length})</summary>${(state.study.protocolHistory||[]).slice().reverse().map(entry=>`<div class="reply"><p>${selectionLabel(entry)}</p><p>${escape(entry.reason)}</p><p class="record-meta">${escape(entry.actor)} · ${date(entry.at)}</p></div>`).join('')||'<p>No prior designation events.</p>'}</details>`:linkView('activity','Manage protocol designation')}</section>`;
}

let importDraft=null;
function importPanel(){if(state.session.user.role!=='Administrator')return '';return `<section class="panel"><h2>Synthetic import rehearsal</h2><p class="screen-note">Requires application administration and current study-group membership. Only synthetic manifests are accepted. Preview accounts for every input record; unresolved records are quarantined, not silently published.</p><form id="import-preview-form"><label class="usa-label" for="import-file">Synthetic manifest JSON</label><input class="usa-file-input" type="file" id="import-file" accept=".json,application/json" required><p class="form-hint">Choose the bundled fixtures/app-import.json or a synthetic manifest in the same schema. No live source connection or real migration is performed.</p><div class="form-row"><button class="usa-button" type="submit">Preview import</button></div></form><div id="import-preview" aria-live="polite"></div><details class="task-history"><summary>Saved import reports</summary><div id="import-reports">Loading reports…</div></details></section>`;}
function renderImportReport(report){const counts=report.counts||{};return `<div class="import-report"><h3>${report.applied?'Applied report':'Preview report'}</h3><p class="screen-note">${report.inputCount} input records · Study revision ${report.studyRevision} · ${date(report.at)}</p><dl class="import-counts">${Object.entries(counts).map(([key,value])=>`<div><dt>${escape(key.replaceAll('_',' '))}</dt><dd>${escape(value)}</dd></div>`).join('')}</dl><p class="screen-note">Quarantined outcomes require correction before they can become study content. A successful apply may include both accepted and quarantined records.</p><ul class="import-outcomes">${(report.outcomes||[]).map(outcome=>`<li><strong>${escape(outcome.sourceId||'Unidentified input')}</strong> · ${escape(outcome.status)}${outcome.reasons?.length?`<p>${outcome.reasons.map(escape).join('; ')}</p>`:''}</li>`).join('')}</ul><details><summary>Manifest integrity</summary><code>${escape(report.manifestSha256)}</code></details></div>`;}
async function loadImportReports(){const id=state.study?.id;try{const reports=await api(`/api/studies/${encodeURIComponent(id)}/imports`);if(state.study?.id===id&&$('#import-reports'))$('#import-reports').innerHTML=reports.length?reports.slice().reverse().map(renderImportReport).join(''):'<p class="screen-note">No import reports saved.</p>';}catch(error){if($('#import-reports'))$('#import-reports').textContent=error.message;}}
document.addEventListener('submit',async event=>{
 const form=event.target;if(form.id!=='import-preview-form')return;event.preventDefault();const button=$('button',form);button.disabled=true;importDraft=null;
 try{const file=$('#import-file').files[0];if(!file||file.size>512*1024)throw new Error('Choose a synthetic JSON manifest no larger than 512 KiB.');const manifest=JSON.parse(await file.text());const studyId=state.study.id;const report=await api(`/api/studies/${encodeURIComponent(studyId)}/imports/preview`,{manifest});if(state.study?.id!==studyId||!$('#import-preview'))return;importDraft={manifest,expectedRevision:report.studyRevision,requestId:crypto.randomUUID(),studyId};$('#import-preview').innerHTML=renderImportReport(report)+'<p class="screen-note">Review all outcomes before applying. This writes accepted synthetic records and saves the report.</p><button class="usa-button" type="button" id="apply-import">Apply previewed manifest</button>';
 }catch(error){notice(error.message,true);}finally{button.disabled=false;}
});
document.addEventListener('click',async event=>{
 if(event.target.id!=='apply-import'||!importDraft)return;const button=event.target;button.disabled=true;
 try{const draft=importDraft;const report=await api(`/api/studies/${encodeURIComponent(draft.studyId)}/imports/apply`,{manifest:draft.manifest,expectedRevision:draft.expectedRevision,requestId:draft.requestId});importDraft=null;await route();notice('Synthetic import applied. Review accepted and quarantined outcomes in the saved report.');if($('#import-preview'))$('#import-preview').innerHTML=renderImportReport(report);
 }catch(error){notice(error.message+' The preview is retained; do not apply against a changed study without reviewing a fresh preview.',true);}finally{button.disabled=false;}
});

function fileReference(id){const file=(state.study.files||[]).find(f=>f.id===id);return file&&fileIsAvailable(file)?`<a href="/api/studies/${encodeURIComponent(state.study.id)}/files/${encodeURIComponent(id)}/download">${escape(file.name)} · file version ${file.version}</a>`:`<span>Unavailable file version (${escape(id)})</span>`;}

function provenanceDetails(record){const source=record.provenance;if(!source)return '';return `<details class="source-provenance"><summary>Historical source provenance</summary><dl><dt>Source workspace</dt><dd>${escape(source.sourceStudyId)}</dd><dt>Source record / revision</dt><dd>${escape(source.sourceId)} / ${escape(source.sourceRevision)}</dd><dt>Original author</dt><dd>${escape(record.author)}</dd><dt>Original time</dt><dd><time datetime="${escape(record.createdAt)}">${escape(record.createdAt)}</time></dd></dl>${source.referenceTargetIds?.length?`<p class="screen-note">Preserved source references</p><ul>${source.referenceTargetIds.map(id=>`<li>${(state.study.files||[]).some(file=>file.id===id)?fileReference(id):itemEvidence(id)}</li>`).join('')}</ul>`:''}<p class="screen-note">Historical attribution does not grant current access.</p></details>`;}

function documentInfo(item){return state.documentWorkspace?.versions.find(version=>version.item.id===item.id);}
function documentReviewSummary(item){const version=documentInfo(item);return `<div class="task-facts"><span class="pill">${escape(version?.status||'Draft')}</span><span>Family ${escape(version?.familyId||item.id)}</span></div><p class="screen-note">Internal document review state; not external study approval. File citations are verified again at acceptance and download.</p>${version?.history.length?`<details class="task-history"><summary>Review history (${version.history.length})</summary>${version.history.map(event=>`<div class="reply"><strong>${escape(event.from)} → ${escape(event.to)}</strong><p>${escape(event.reason)}</p><p class="record-meta">${escape(event.actor)} · ${date(event.at)}</p></div>`).join('')}</details>`:''}`;}
function documentStateActions(item){const info=documentInfo(item);const role=state.documentWorkspace?.studyRole;const buttons=[];if((info?.status||'Draft')==='Draft'&&role!=='None')buttons.push(['Review','Submit for review']);if(info?.status==='Review'&&['Reviewer','StudyLead'].includes(role))buttons.push(['Draft','Return to draft']);if(info?.status==='Review'&&role==='StudyLead')buttons.push(['Accepted','Accept version']);if(info?.status==='Accepted'&&role==='StudyLead')buttons.push(['Superseded','Supersede version']);return buttons.map(([status,label])=>`<button class="text-button" data-action="document-state" data-state="${status}" data-id="${escape(item.id)}">${label}</button>`).join('');}
function documentFamilies(){const families=new Map();for(const version of state.documentWorkspace?.versions||[]){if(!families.has(version.familyId))families.set(version.familyId,[]);families.get(version.familyId).push(version);}return [...families.values()].map(versions=>{versions.sort((a,b)=>b.item.version-a.item.version);return `<section class="document-family"><h3>${escape(versions[0].item.title)}</h3><p class="screen-note">${versions.length} immutable ${versions.length===1?'version':'versions'} · Your study role: ${escape(state.documentWorkspace.studyRole)}</p>${versions.map(v=>record(v.item)).join('')}</section>`;}).join('');}
function showDocumentEditor(source,revision){const editor=$('#editor');if(!editor)return;editor.innerHTML=`<section class="form-panel"><h3>${revision?'Create immutable document version':'Create document family'}</h3><form id="document-form" data-previous="${revision?escape(source.id):''}" data-revision="${state.study.revision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="item-title">Document title</label><input class="usa-input" id="item-title" name="title" required maxlength="180" value="${revision?escape(source.title):''}"><label class="usa-label" for="item-body">Version content</label><textarea class="usa-textarea" id="item-body" name="body" required maxlength="20000">${revision?escape(source.body):''}</textarea><p class="form-hint">Saves a new Draft version with its own author and time. Earlier content and review history remain unchanged; renaming does not change the document family.</p>${fileEvidencePicker('fileIds',revision?source.fileIds||[]:[])}<div class="form-row"><button class="usa-button" type="submit">Save draft version</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;$('#item-title').focus();}
function showDocumentStateEditor(item,status){$('#editor').innerHTML=`<section class="form-panel"><h3>${escape(item.title)} → ${escape(status)}</h3><form id="document-state-form" data-version="${escape(item.id)}" data-state="${status}" data-revision="${state.study.revision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="document-state-reason">Reason for review-state change</label><textarea class="usa-textarea" name="reason" id="document-state-reason" required maxlength="1000"></textarea><p class="form-hint">This records an internal study-document decision. It does not grant external approval or change the current protocol selection.</p><div class="form-row"><button class="usa-button" type="submit">Confirm ${escape(status)}</button><button class="text-button" type="button" data-action="cancel">Cancel</button></div><p id="form-error" class="form-hint" role="alert"></p></form></section>`;$('#document-state-reason').focus();}
function handoffWorkspace(){return `<div class="content-heading"><h2>Handoff snapshots</h2></div><p class="section-description">Capture a fixed study packet for orientation or handoff. Later edits do not rewrite it; current access and source-removal restrictions still apply.</p><section class="panel"><h3>Capture a handoff</h3><form id="handoff-form" data-revision="${state.study.revision}" data-request="${crypto.randomUUID()}"><label class="usa-label" for="handoff-title">Snapshot title</label><input class="usa-input" id="handoff-title" name="title" required maxlength="180"><label class="usa-label" for="handoff-summary">Scope, assumptions, open questions, and owners</label><textarea class="usa-textarea" id="handoff-summary" name="summary" required maxlength="2000"></textarea><label class="usa-label" for="handoff-mode">Evidence selection</label><select class="usa-select" id="handoff-mode" name="mode"><option value="default">Default study packet with linked evidence</option><option value="explicit">Only explicitly checked records and files below</option></select><details class="task-history"><summary>Choose explicit evidence (optional)</summary><fieldset class="evidence-picker"><legend>Study records</legend>${items().filter(item=>['document','documentation','decision','task','discussion','reply','idea'].includes(item.kind)).map(item=>`<label><input type="checkbox" name="itemIds" value="${escape(item.id)}">${escape(item.title)} · ${escape(item.kind)} version ${item.version}</label>`).join('')}</fieldset>${fileEvidencePicker('fileIds',[])}</details><p class="form-hint">Default capture includes current study guidance, decisions, tasks, conversations, protocol, and linked evidence. If a file is quarantined or evidence unavailable, choose an explicit set of available records and files. Linked evidence is always included. Capturing a snapshot is not formal approval.</p><div class="form-row"><button class="usa-button" type="submit">Capture snapshot</button></div><p id="handoff-error" class="form-hint" role="alert"></p></form></section><section class="panel"><h3>Saved snapshots</h3><div id="handoff-list">Loading snapshots…</div></section><div id="handoff-detail"></div>`;}
async function loadHandoffs(){const studyId=state.study?.id;try{const snapshots=await api(`/api/studies/${encodeURIComponent(studyId)}/handoffs`);if(state.study?.id!==studyId||!$('#handoff-list'))return;$('#handoff-list').innerHTML=snapshots.length?snapshots.slice().reverse().map(snapshot=>`<article class="record"><h3>${escape(snapshot.title)}</h3><p>${escape(snapshot.summary)}</p><p class="record-meta">${escape(snapshot.createdBy)} · ${date(snapshot.createdAt)} · Study revision ${snapshot.sourceRevision} · ${snapshot.itemCount} records / ${snapshot.fileCount} files</p><button class="text-button" data-action="view-handoff" data-snapshot="${escape(snapshot.id)}">View snapshot</button></article>`).join(''):'<p class="muted">No snapshots yet.</p>';}catch(error){if($('#handoff-list'))$('#handoff-list').textContent=error.message;}}
function renderHandoff(snapshot){const evidence=id=>{const captured=snapshot.items.find(entry=>entry.item?.id===id);if(captured)return captured.available?`${escape(captured.item.title)} · ${escape(captured.item.kind)} version ${captured.item.version}`:'Unavailable captured record';const file=snapshot.files.find(entry=>entry.file?.id===id);return file?.available?`<a href="/api/studies/${encodeURIComponent(state.study.id)}/files/${encodeURIComponent(id)}/download">${escape(file.file.name)} · file version ${file.file.version}</a>`:'Unavailable captured evidence';};return `<section class="panel handoff-capture" tabindex="-1"><p class="eyebrow">Immutable handoff capture</p><h2>${escape(snapshot.title)}</h2><p>${escape(snapshot.summary)}</p><p class="record-meta">${escape(snapshot.createdBy)} · ${escape(snapshot.createdAt)} · Source revision ${snapshot.sourceRevision}</p><p class="screen-note">${escape(snapshot.studyTitle)} · Captured workspace stage: ${escape(snapshot.studyStage)}</p>${snapshot.redacted?'<div class="notice error">Some captured sources are now unavailable. Their restricted content is omitted from this view.</div>':''}<div class="integration"><strong>Captured protocol reference</strong>${snapshot.currentProtocol?`${snapshot.protocolAvailable?evidence(snapshot.currentProtocol.id):'Unavailable captured protocol'}<p>${escape(snapshot.currentProtocol.reason)}</p>`:'No protocol designated at capture.'}</div><h3 class="handoff-section-heading">Captured study records</h3>${snapshot.items.map(entry=>entry.available?`<article class="record"><p class="record-meta">${escape(entry.item.kind)} · Version ${entry.item.version} · ${escape(entry.item.author)} · ${escape(entry.item.createdAt)}</p><h3>${escape(entry.item.title)}</h3>${entry.review?`<span class="pill">Captured state: ${escape(entry.review.status)}</span>${capturedReviewHistory(entry.review)}`:''}${capturedProvenance(entry.item,evidence)}<p>${escape(entry.item.body)}</p>${entry.item.task?`<p class="screen-note">Captured task: ${escape(entry.item.task.status)} · Owner: ${escape(entry.item.task.assignee||'Unassigned')} · Due: ${escape(entry.item.task.dueDate||'Not set')}</p>`:''}<p class="screen-note">${[entry.item.documentId,...(entry.item.fileIds||[]),...(entry.item.task?.links||[]),...(entry.item.task?.fileLinks||[])].filter(Boolean).map(evidence).join(' · ')}</p></article>`:`<article class="record"><h3>Unavailable captured record</h3><p>${escape(entry.reason||'Current source restrictions apply.')}</p></article>`).join('')}<h3 class="handoff-section-heading">Captured file versions</h3>${snapshot.files.map(entry=>entry.available?`<article class="record"><h3>${evidence(entry.file.id)}</h3><p class="record-meta">${escape(entry.file.author)} · ${escape(entry.file.createdAt)} · ${entry.file.size} bytes</p><p class="screen-note">SHA-256 <code>${escape(entry.file.sha256)}</code></p>${capturedProvenance(entry.file,evidence)}</article>`:`<article class="record"><h3>Unavailable captured file</h3><p>${escape(entry.reason||'Current source restrictions apply.')}</p></article>`).join('')}<details><summary>Capture integrity</summary><p class="screen-note">${escape(snapshot.digestScope)}</p><code>${escape(snapshot.sha256)}</code></details></section>`;}
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='handoff-form')return;event.preventDefault();const button=$('button',form);button.disabled=true;try{const fields=new FormData(form);const payload={title:fields.get('title'),summary:fields.get('summary'),expectedRevision:Number(form.dataset.revision),requestId:form.dataset.request};if(fields.get('mode')==='explicit'){payload.itemIds=fields.getAll('itemIds');payload.fileIds=fields.getAll('fileIds');}const snapshot=await api(`/api/studies/${encodeURIComponent(state.study.id)}/handoffs`,payload);await route();if($('#handoff-detail')){$('#handoff-detail').innerHTML=renderHandoff(snapshot);$('.handoff-capture').focus();}notice('Immutable handoff snapshot captured.');}catch(error){notice(error.message,true);$('#handoff-error').textContent='Your input is retained. Review a fresh study revision before retrying a stale capture.';}finally{button.disabled=false;}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action="view-handoff"]');if(!button)return;button.disabled=true;try{const snapshot=await api(`/api/studies/${encodeURIComponent(state.study.id)}/handoffs/${encodeURIComponent(button.dataset.snapshot)}`);if($('#handoff-detail')){$('#handoff-detail').innerHTML=renderHandoff(snapshot);$('.handoff-capture').focus();}}catch(error){notice(error.message,true);}finally{button.disabled=false;}});

function capturedReviewHistory(review){return review.history?.length?`<details class="task-history"><summary>Captured review history (${review.history.length})</summary>${review.history.map(event=>`<div class="reply"><strong>${escape(event.from)} → ${escape(event.to)}</strong><p>${escape(event.reason)}</p><p class="record-meta">${escape(event.actor)} · <time datetime="${escape(event.at)}">${escape(event.at)}</time></p></div>`).join('')}</details>`:'';}
function capturedProvenance(record,resolveEvidence){const source=record.provenance;if(!source)return '';return `<details class="source-provenance"><summary>Captured source provenance</summary><dl><dt>Source workspace</dt><dd>${escape(source.sourceStudyId)}</dd><dt>Source record / revision</dt><dd>${escape(source.sourceId)} / ${escape(source.sourceRevision)}</dd><dt>Original author</dt><dd>${escape(record.author)}</dd><dt>Original time</dt><dd><time datetime="${escape(record.createdAt)}">${escape(record.createdAt)}</time></dd></dl>${source.referenceTargetIds?.length?`<p class="screen-note">References within this capture</p><ul>${source.referenceTargetIds.map(id=>`<li>${resolveEvidence(id)}</li>`).join('')}</ul>`:''}<p class="screen-note">Captured historical attribution does not grant current access.</p></details>`;}
